sys_script_client.script:
function onLoad() {
    var requestedFor = g_form.getValue('u_requested_for');

    if (!requestedFor) {
        g_form.clearValue('u_requested_for_email');
        return;
    }

    var ga = new GlideAjax('GetEmailAddress');
    ga.addParam('sysparm_name', 'getEmail');
    ga.addParam('sysparm_userID', requestedFor);
    ga.getXML(function(response) {
        var correctEmail = response.responseXML.documentElement.getAttribute('answer');
        var currentEmail = g_form.getValue('u_requested_for_email');

        if (!correctEmail) {
            g_form.clearValue('u_requested_for_email');
            return;
        }

        if (currentEmail !== correctEmail) {
            g_form.setValue('u_requested_for_email', correctEmail);
        }
    });
}
